document.addEventListener("DOMContentLoaded", function () {
  const btnViewAll = document.querySelector("#btn-view-all-events");
  const btnLink = btnViewAll?.querySelector("a");
  const checkboxes = document.querySelectorAll(
    ".jet-checkboxes-list__input[name='events-categories']"
  );

  // 1. Adiciona classe .ativo no botão View All ao carregar a página
  btnViewAll?.classList.add("ativo");

  // 2. Clique no botão "View All"
  btnLink?.addEventListener("click", function (e) {
    e.preventDefault();

    // Marca botão como ativo
    btnViewAll.classList.add("ativo");

    // Desmarca todos os checkboxes
    checkboxes.forEach((cb) => {
      cb.checked = false;
    });

    // Dispara o filtro usando change (no primeiro checkbox só pra forçar o AJAX)
    if (checkboxes.length) {
      checkboxes[0].dispatchEvent(new Event("change", { bubbles: true }));
    }
  });

  // 3. Ao clicar em um checkbox (categoria)
  checkboxes.forEach((cb) => {
    cb.addEventListener("change", function () {
      if (this.checked) {
        // Remove .ativo do botão View All
        btnViewAll.classList.remove("ativo");

        // Desmarca os outros checkboxes
        checkboxes.forEach((other) => {
          if (other !== this) other.checked = false;
        });

        // Reforça o filtro com um novo change
        this.dispatchEvent(new Event("change", { bubbles: true }));
      }
    });
  });
});

document.addEventListener('DOMContentLoaded', function () {
  if (window.innerWidth > 768) return; // Só aplica em mobile

  const filterWrapper = document.querySelector('.event-filters');
  const checkboxes = document.querySelectorAll('.jet-checkboxes-list__input');

  if (!filterWrapper || checkboxes.length === 0) return;

  // Cria o <select>
  const select = document.createElement('select');
  select.id = 'mobile-category-select';

  // Adiciona opção "View all"
  const defaultOption = document.createElement('option');
  defaultOption.value = 'view-all';
  defaultOption.textContent = 'View all';
  select.appendChild(defaultOption);

  // Adiciona cada categoria como opção no <select>
  checkboxes.forEach(cb => {
    const label = cb.getAttribute('data-label');
    const value = cb.value;

    const option = document.createElement('option');
    option.value = value;
    option.textContent = label;
    select.appendChild(option);
  });

  // Insere o select antes do botão de view all
  const btnViewAll = document.getElementById('btn-view-all-events');
  filterWrapper.insertBefore(select, btnViewAll);

  // Lógica ao trocar o select
  select.addEventListener('change', () => {
    const selected = select.value;

    // Desmarca todos
    checkboxes.forEach(cb => { cb.checked = false; });

    if (selected === 'view-all') {
      // Força filtro reset ao simular clique no botão "view all"
      btnViewAll?.querySelector('a')?.click();
    } else {
      // Marca o checkbox correspondente
      const cbToCheck = Array.from(checkboxes).find(cb => cb.value === selected);
      if (cbToCheck) {
        cbToCheck.checked = true;
        // Dispara evento de mudança para aplicar filtro
        cbToCheck.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }
  });
});